*/
html,
body {
  margin: 0;
  padding: 0;
  padding-top: 1px;
  position: relative;
  font-family: "Inter", sans-serif;
  font-weight: normal;
}

/* materials Icons */
.material-icons-outlined {
  font-family: "Material Icons Outlined";
  font-weight: normal;
  font-style: normal;
  font-size: 24px;
  /* Preferred icon size */
  display: inline-block;
  line-height: 1;
  text-transform: none;
  letter-spacing: normal;
  word-wrap: normal;
  white-space: nowrap;
  direction: ltr;
  /* Support for all WebKit browsers. */
  -webkit-font-smoothing: antialiased;
  /* Support for Safari and Chrome. */
  text-rendering: optimizeLegibility;
  /* Support for Firefox. */
  -moz-osx-font-smoothing: grayscale;
  /* Support for IE. */
  font-feature-settings: "liga";
}

.material-symbols-outlined {
  font-variation-settings: "FILL" 0, "wght" 400, "GRAD" 0, "opsz" 24;
}

a {
  text-decoration: none;
  display: inline-block;
  color: #1d1d1b;
}

a:hover {
  color: #1d1d1b;
}

h1, .h1 {
  font-size: 40px;
  font-weight: 500;
  font-stretch: normal;
  font-style: normal;
  line-height: normal;
  letter-spacing: normal;
  color: #1d1d1b;
}

h2, .h2 {
  font-size: 30px;
  font-weight: 500;
  font-stretch: normal;
  font-style: normal;
  line-height: normal;
  letter-spacing: normal;
  color: #1d1d1b;
}

main {
  color: #1d1d1b;
}

.main {
  padding-top: 130px;
  color: #1d1d1b;
}

@media (max-width: 1280px) {
  .main {
    padding-top: 64px;
  }
}
.display-none {
  display: none;
}

/* Back to */
.backto a {
  display: inline-block;
  color: #1e1e24;
}

.backto span {
  font-size: inherit;
}

